  useEffect(()=>{if(!desktop)return;const watcher=observeDesktopWindow({focus:focused=>{if(focused){refreshProviders();void fetchState();}}});return watcher.dispose;},[fetchState,refreshProviders]);
  useEffect(()=>{if(!desktop)return;const openLink=(event:MouseEvent)=>{const anchor=event.target instanceof Element?event.target.closest<HTMLAnchorElement>('a[href][target="_blank"]'):null;if(!anchor||event.defaultPrevented)return;event.preventDefault();void openDesktopHttps(anchor.href).catch(()=>notify(t.error));};document.addEventListener('click',openLink);return()=>document.removeEventListener('click',openLink);},[notify,t.error]);
