  const events=sortedEvents(snapshot.events.filter(e=>activeGroup==='all'||e.groupId===activeGroup));
  const availability=(snapshot.availability||[]).filter(item=>activeGroup==='all'||item.groupId===activeGroup);
  const dayAvailability=availability.filter(item=>item.date===selectedDate);
  const dayEvents=events.filter(e=>e.date===selectedDate);
  const upcoming=events.filter(e=>`${e.date}T${e.endTime}`>=`${dateKey(new Date())}T${new Date().toTimeString().slice(0,5)}`);
  const featured=upcoming[0];
  const selectedEvent=snapshot.events.find(e=>e.id===modal?.eventId);
  const selectedGroup=snapshot.groups.find(g=>g.id===modal?.groupId);
